from dataclasses import dataclass

import pytest


class BoundedQueue:
    """Fixed-capacity FIFO queue of ints with a non-blocking put."""

    def __init__(self, capacity: int) -> None:
        """Create an empty queue that holds at most capacity items."""
        self._capacity: int = capacity
        self._items: list[int] = []

    def try_put(self, item: int) -> bool:
        """Append item if there is room. Return True if accepted, False if full. Never blocks."""
        if len(self._items) < self._capacity:
            self._items.append(item)
            return True
        return False


def accepted(cap: int, xs: list[int]) -> int:
    """Put each element of xs into a queue of capacity cap without blocking.

    Stop at the first put that is rejected because the queue is full.
    Return the number of puts accepted before that point.
    """
    q = BoundedQueue(cap)
    count = 0
    for x in xs:
        if not q.try_put(x):
            break
        count += 1
    return count


def test_accepted_stops_at_capacity() -> None:
    assert accepted(3, [1, 2, 3, 4, 5]) == 3


def test_accepted_fewer_items_than_capacity() -> None:
    assert accepted(10, [1, 2]) == 2


def test_accepted_empty_input() -> None:
    assert accepted(4, []) == 0


def test_accepted_zero_capacity() -> None:
    assert accepted(0, [1, 2, 3]) == 0


def test_accepted_negative_capacity_treated_as_full() -> None:
    assert accepted(-1, [1]) == 0


def test_bounded_queue_try_put_full() -> None:
    q = BoundedQueue(1)
    assert q.try_put(1) is True
    assert q.try_put(2) is False
